BEGIN;

CREATE TABLE public.order_status_assignments (
	id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
	order_id integer NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE ON UPDATE CASCADE,
	status_id integer REFERENCES public.order_statuses(id) ON DELETE RESTRICT ON UPDATE CASCADE,
	recorder jsonb,
	is_active boolean NOT NULL DEFAULT true,
	recorded_at timestamp with time zone NOT NULL DEFAULT clock_timestamp(),
	CHECK (recorder IS NULL OR ( jsonb_typeof(recorder) = 'object' AND recorder ? 'document_type' AND recorder ? 'document_id' AND jsonb_typeof(recorder->'document_type') = 'string' AND recorder->>'document_type' ~ '^[a-z][a-z0-9_]*$' AND jsonb_typeof(recorder->'document_id') = 'number' AND recorder->>'document_id' ~ '^[1-9][0-9]*$' ))
);

COMMENT ON TABLE public.order_status_assignments IS 'Reversible order status history, including manual assignments.';
COMMENT ON COLUMN public.order_status_assignments.recorder IS 'Null for manual assignments; otherwise document_type and document_id.';

WITH required(code, description) AS (
	VALUES
		('orderStatusAssignment.list', 'Просмотр истории статусов заказа'),
		('orderStatusAssignment.detail', 'Просмотр записи статуса заказа')
)
INSERT INTO public.permissions (code, description)
SELECT required.code, required.description
FROM required
ON CONFLICT (code) DO UPDATE
SET description = EXCLUDED.description;

WITH roles(role_id) AS (
	VALUES
		('admin'::public.role_types)
), required(permission_code) AS (
	VALUES
		('orderStatusAssignment.list'),
		('orderStatusAssignment.detail')
)
INSERT INTO public.role_permissions (role_id, permission_code)
SELECT roles.role_id, required.permission_code
FROM roles
CROSS JOIN required
ON CONFLICT DO NOTHING;

COMMIT;
